INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (2179376, 655441, 'Liquidador/a de Impuestos', 'Lorelein Gonzalez', 'Liquidador/a de Impuestos Resumen del Puesto Estamos en la búsqueda de un/a Liquidador/a de Impuestos con experiencia para integrarse a nuestro equipo. El/la candidato/a ideal poseerá un sólido conocimiento en materia impositiva y será capaz de gestionar eficientemente las obligaciones fiscales. Responsabilidades Realizar la liquidación de impuestos nacionales y provinciales. Gestionar y operar en las páginas web de los organismos fiscales correspondientes. Utilizar y dominar el paquete Office para la elaboración de informes y análisis. Asegurar el cumplimiento de las normativas fiscales vigentes. Colaborar con otras áreas para la correcta presentación de la información. Requisitos Experiencia comprobable en liquidación de impuestos nacionales y provinciales. Dominio del paquete Office (Word, Excel, etc.). Capacidad para el manejo de plataformas web de organismos fiscales. Orientación al detalle y precisión en el trabajo. Habilidad para trabajar de forma autónoma y en equipo. Disponibilidad para modalidad presencial y jornada completa.', 0, 'Capital Federal, Buenos Aires', 'Presencial', 'Full-time', '10-04-2026', '10-04-2026 13:40:56', '10-04-2026 13:42:01', '2026-04-10', '2026-04-10', '2026-04-10', '2026-04-10T00:00:00-03:00', '2026-04-10T13:40:56-03:00', '2026-04-10T13:42:01-03:00', 1, 0, 1, 90, 1, NULL, 0, 0, NULL, 2001, 'Freemium', 'zonajobs', 'freemium', 0, 0, 0, NULL, NULL, 'https://www.zonajobs.com.ar/aviso/2179376', '2026-04-13T08:11:19.978915');
