, '10-04-2026', '10-04-2026 16:53:56', '10-04-2026 16:58:46', '2026-04-10', '2026-04-10', '2026-04-10', '2026-04-10T00:00:00-03:00', '2026-04-10T16:53:56-03:00', '2026-04-10T16:58:46-03:00', 1, 0, 6, 35, 1, 'https://imgzj.jobscdn.com/portal/img/empresas/1/static/logoMainPic_624405_bum_vc40b283d.jpg', 1, 0, NULL, 40, 'Avisos Gold', 'zonajobs', 'destacado', 1, 0, 0, NULL, NULL, 'https://www.zonajobs.com.ar/aviso/2179414', '2026-04-13T08:12:41.174529');
